import React from 'react'

function ThemeButton(props: any) {
  return (
    <div>
      <label className="switch">
        <input type="checkbox" onClick={props.switchTheme}></input>
      <span className="slider round"></span>
    </label>
    </div>
  )
}

function Navbar() {
  return (
    <div>
        <nav className="nav">
            <a href="#" className="name">KJ</a>
            <ThemeButton/>
        </nav>
    </div>
  )
}

export default Navbar;
